#include <iostream>

int main() {
    int a{7};
    int* aPtr{&a};

    std::cout << "The value of a is " << a << "\n";
    std::cout << "The value of *aPtr is " << *aPtr << "\n";

    // Dereferencing as an lvalue to mutate the target
    *aPtr = 42;
    std::cout << "After *aPtr = 42, a is " << a << "\n";
    std::cout << "The value of *aPtr is " << *aPtr << "\n";

    return 0;
}

#include <iostream>

// Pass-by-value: computes cube on a copy and returns result
int cubeByValue(int n) {
    return n * n * n;
}

// Pass-by-reference with pointer: directly modifies caller's variable
void cubeByReference(int* nPtr) {
    if (nPtr != nullptr) {
        *nPtr = (*nPtr) * (*nPtr) * (*nPtr);
    }
}

int main() {
    int val1{5};
    int val2{5};

    std::cout << "val1 before cubeByValue: " << val1 << "\n";
    val1 = cubeByValue(val1);
    std::cout << "val1 after cubeByValue: " << val1 << "\n";

    std::cout << "val2 before cubeByReference: " << val2 << "\n";
    cubeByReference(&val2);
    std::cout << "val2 after cubeByReference: " << val2 << "\n";

    return 0;
}
